	public MCCallerPanelBridge createBridge(String id) {
		if (id.equals("MS.MSBCL1040.Srch01")) {
			return new MS_MSBCL1040_Srch01Bridge();
		}
		if (id.equals("MS.MSBCL1040.Upd01")) {
			return new MS_MSBCL1040_Upd01Bridge();
		}
		if (id.equals("MS.MSBCL1040.Del01")) {
			return new MS_MSBCL1040_Del01Bridge();
		}
		if (id.equals("MS.MSBCL1040.Upd02")) {
			return new MS_MSBCL1040_Upd02Bridge();
		}
		if (id.equals("MS.MSBCL1040.Del02")) {
			return new MS_MSBCL1040_Del02Bridge();
		}
		if (id.equals("MS.MSBCL1040.Prnt01")) {
			return new MS_MSBCL1040_Prnt01Bridge();
		}
		if (id.equals("MS.MSBCL1040.Sprt01")) {
			return new MS_MSBCL1040_Sprt01Bridge();
		}
		return super.createBridge(id);
	}
